const supplierInput = this.getInputData(1)
const allowlist = new Set()
let supplierDocuments = []
for (const item of supplierInput) {
  const data = item.json || {}
  if (Array.isArray(data.allowedSupplierEmails)) {
    for (const email of data.allowedSupplierEmails) {
      if (typeof email === 'string' && email.trim()) {
        allowlist.add(email.trim().toLowerCase())
      }
    }
  }
  if (Array.isArray(data.supplierDocuments)) {
    supplierDocuments = supplierDocuments.concat(data.supplierDocuments)
  }
}
if (!allowlist.size) {
  return []
}
const emailPattern = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi
const collectAttachments = part => {
  const results = []
  if (!part || typeof part !== 'object') {
    return results
  }
  if (part.filename && part.body && part.body.attachmentId) {
    results.push(part)
  }
  if (Array.isArray(part.parts)) {
    for (const child of part.parts) {
      results.push(...collectAttachments(child))
    }
  }
  return results
}
const outputs = []
for (const item of items) {
  const message = item.json || {}
  const payload = message.payload || {}
  const headers = Array.isArray(payload.headers) ? payload.headers : []
  const headerMap = new Map()
  for (const header of headers) {
    if (header && header.name) {
      headerMap.set(header.name.toLowerCase(), header.value || '')
    }
  }
  const fromHeader = headerMap.get('from') || ''
  const subject = headerMap.get('subject') || ''
  const dateHeader = headerMap.get('date') || ''
  const matched = []
  const fromMatches = fromHeader.match(emailPattern) || []
  for (const match of fromMatches) {
    const email = match.trim().toLowerCase()
    if (allowlist.has(email)) {
      if (!matched.includes(email)) {
        matched.push(email)
      }
    }
  }
  if (!matched.length) {
    continue
  }
  const attachments = collectAttachments(payload)
  for (const part of attachments) {
    const attachmentId = part.body?.attachmentId
    if (!attachmentId) {
      continue
    }
    const fileName = part.filename || 'attachment.pdf'
    const mimeType = part.mimeType || 'application/pdf'
    const isPdf = fileName.toLowerCase().endsWith('.pdf') || mimeType.toLowerCase() === 'application/pdf'
    if (!isPdf) {
      continue
    }
    outputs.push({
      json: {
        messageId: message.id || '',
        threadId: message.threadId || '',
        historyId: message.historyId || '',
        snippet: message.snippet || '',
        subject,
        emailDate: dateHeader,
        attachmentId,
        attachmentName: fileName,
        mimeType,
        source: 'gmail',
        gmailAccount: message.gmailAccount || '',
        allowedSupplierEmails: Array.from(allowlist),
        matchedSupplierEmails: matched,
        primarySupplierEmail: matched[0] || null,
        supplierAllowlistEnforced: true,
        supplierDocuments
      }
    })
  }
}
return outputs

return items.map(item => {
  const json = item.json || {}
  const binary = item.binary || {}
  const attachmentName = json.attachmentName || 'invoice.pdf'
  const mimeType = json.mimeType || 'application/pdf'
  const emailMetadata = {
    messageId: json.messageId || '',
    threadId: json.threadId || '',
    historyId: json.historyId || '',
    snippet: json.snippet || '',
    subject: json.subject || '',
    emailDate: json.emailDate || '',
    attachmentName,
    mimeType,
    source: json.source || 'gmail',
    gmailAccount: json.gmailAccount || '',
    supplierAllowlistEnforced: Boolean(json.supplierAllowlistEnforced),
    allowedSupplierEmails: Array.isArray(json.allowedSupplierEmails) ? json.allowedSupplierEmails : [],
    matchedSupplierEmails: Array.isArray(json.matchedSupplierEmails) ? json.matchedSupplierEmails : [],
    primarySupplierEmail: json.primarySupplierEmail || null,
    supplierDocuments: Array.isArray(json.supplierDocuments) ? json.supplierDocuments : []
  }
  const base64 = binary.data && binary.data.data ? binary.data.data : (json.data || json.attachmentData || '')
  return {
    json: {
      emailMetadata,
