const emailPattern = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi
const collected = new Set()
const documentIds = new Set()
const visit = value => {
  if (value === null || value === undefined) {
    return
  }
  if (typeof value === 'string') {
    const matches = value.match(emailPattern) || []
    for (const match of matches) {
      collected.add(match.trim().toLowerCase())
    }
    return
  }
  if (Array.isArray(value)) {
    for (const entry of value) {
      visit(entry)
    }
    return
  }
  if (typeof value === 'object') {
    if (Object.prototype.hasOwnProperty.call(value, 'stringValue')) {
      visit(value.stringValue)
      return
    }
    if (value.arrayValue && Array.isArray(value.arrayValue.values)) {
      visit(value.arrayValue.values)
    }
    if (value.mapValue && value.mapValue.fields) {
      visit(value.mapValue.fields)
    }
    for (const entry of Object.values(value)) {
      visit(entry)
    }
  }
}
for (const item of items) {
  const json = item.json || {}
  if (json.name || json.id) {
    documentIds.add((json.name || json.id).toString())
  }
  visit(json)
}
const emails = Array.from(collected).sort((a, b) => a.localeCompare(b))
return [{
  json: {
    allowedSupplierEmails: emails,
    supplierAllowlistEnforced: true,
    supplierDocuments: Array.from(documentIds)
  }
}]

const loadPdfModule = async () => {
  try {
    const imported = await import('pdf-parse')
    return imported.default || imported
  } catch (error) {
    throw new Error('Failed to load pdf-parse module. Install it in your n8n instance (npm install pdf-parse).')
  }
}
const pdfParse = await loadPdfModule()
